package dk.stream.android;
import android.content.Context;
import androidx.appcompat.app.AlertDialog;
final class FavoritePicker {
 interface Save {boolean apply(Runnable change);}
 static void show(Context context,Library library,Save save,FavoriteLists.Item item,Runnable changed){if(item.stream!=null&&item.stream.channel.kind==Playlist.Kind.TV){int[] selected={TvFavorites.mask(library,item.stream)};if(!library.isFavorite(item.stream))selected[0]=1;boolean[] checked=new boolean[4];for(int i=0;i<4;i++)checked[i]=(selected[0]&(1<<i))!=0;new AlertDialog.Builder(context).setTitle(UiText.text("Vælg TV-favoritlister")).setMultiChoiceItems(UiText.labels(new String[]{"TV-Favoritliste 1","TV-Favoritliste 2","TV-Favoritliste 3","TV-Favoritliste 4"}),checked,(dialog,index,on)->{if(on)selected[0]|=1<<index;else selected[0]&=~(1<<index);}).setPositiveButton(UiText.text("Gem"),(dialog,which)->{if(save.apply(()->TvFavorites.set(library,item.stream,selected[0])))changed.run();}).setNegativeButton(UiText.text("Annuller"),null).show();return;}java.util.List<String> available=new java.util.ArrayList<>();for(String name:library.favoriteHomeOrder)if(FavoriteLists.homeAllowed(item,name))available.add(name);String[] names=available.toArray(new String[0]);new AlertDialog.Builder(context).setTitle(UiText.text("Vælg favoritliste")).setItems(UiText.labels(names),(dialog,position)->{if(save.apply(()->FavoriteLists.assignHome(library,item,names[position])))changed.run();}).setNegativeButton(UiText.text("Annuller"),null).show();}
 static void podcast(android.widget.PopupMenu menu,Library library,Save save,FavoriteLists.Item item,Runnable changed){if(!FavoriteLists.homeAllowed(item,"Podcast"))return;menu.getMenu().add(UiText.text("Tilføj til Podcast")).setOnMenuItemClickListener(choice->{if(save.apply(()->FavoriteLists.assignHome(library,item,"Podcast")))changed.run();return true;});}
 private FavoritePicker(){}
}
